"""Exact archived fit QP with trust-unit variables and positive global objective scaling."""
import argparse,datetime,json,hashlib
from pathlib import Path
import numpy as np,scipy.sparse as sp,osqp
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--directory',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();P=sp.load_npz(a.directory/'linear_failed_P.npz');A=sp.load_npz(a.directory/'linear_failed_A.npz');z=np.load(a.directory/'linear_failed_vectors.npz');q=z['gradient'];l=z['lower'];u=z['upper'];n=len(q)//17;cs=np.tile(np.r_[np.repeat(.005,3),np.repeat(.05,14)],n);C=sp.diags(cs);H=(C@P@C).tocsc();objective_scale=float(H.diagonal().max());H=H/objective_scale;g=cs*q/objective_scale;B=(A@C).tocsc();rs=1/np.maximum(np.asarray(abs(B).max(axis=1).toarray()).ravel(),1e-12);D=sp.diags(rs);solver=osqp.OSQP();solver.setup(P=sp.triu(H,format='csc'),q=g,A=(D@B).tocsc(),l=rs*l,u=rs*u,verbose=False,eps_abs=1e-8,eps_rel=1e-8,max_iter=100000,polishing=True);res=solver.solve();step=cs*res.x;ax=A@step;violation=np.maximum.reduce([np.zeros(len(l)),l-ax,ax-u]);lam=objective_scale*rs*res.y;stationarity=P@step+q+A.T@lam;relative_stationarity=float(np.linalg.norm(stationarity,np.inf)/max(1,np.linalg.norm(P@step,np.inf),np.linalg.norm(q,np.inf),np.linalg.norm(A.T@lam,np.inf)));objective=lambda t:float(.5*t@(P@t)+q@t);rng=np.random.default_rng(42);test=rng.normal(size=len(q))*.001;transformed=float((.5*(test/cs)@(H@(test/cs))+g@(test/cs))*objective_scale);equiv=abs(transformed-objective(test))/max(1,abs(objective(test)));assert equiv<1e-10
np.savez_compressed(a.output.parent/'physical_scaling_same_qp_step.npz',step=step,column_scale=cs,row_scale=rs,objective_scale=objective_scale,solver_dual=res.y)
out=dict(time_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Exact archived first-fit P/A/q/bounds; trust-unit coordinate change and positive global objective scaling only, not nonlinear/physics/training acceptance.',status=res.info.status,iterations=res.info.iter,objective_scale=objective_scale,equivalent_objective_relative_error=equiv,unscaled_constraint_violation=float(violation.max()),worst_row=int(violation.argmax()),original_unit_gate_pass=bool(res.info.status_val==1 and violation.max()<=1e-7),relative_original_stationarity=relative_stationarity,archived_objective=objective(z['step']),new_objective=objective(step),zero_objective=objective(np.zeros(len(q))),scaled_constraint_value_abs_max=float(abs(D@ax).max()),primal_residual=res.info.prim_res,dual_residual=res.info.dual_res,source_hashes={name:hashlib.sha256((a.directory/name).read_bytes()).hexdigest() for name in ['linear_failed_P.npz','linear_failed_A.npz','linear_failed_vectors.npz']});a.output.write_text(json.dumps(out,indent=2)+'\n');print(out,flush=True)
